const { withAndroidManifest } = require("expo/config-plugins");

/**
 * Marks portrait as optional for Google Play.
 *
 * `"orientation": "portrait"` in app.json sets `screenOrientation="portrait"`
 * on MainActivity, and Play reads that as a REQUIRED `android.hardware.screen.portrait`:
 * the Console then warns that devices without it (some tablets, desktop
 * Chromebooks, XR) can't install the app. The app still locks to portrait; this
 * only tells Play a device that can't be held upright may install it anyway.
 *
 * `android/` is regenerated by `expo prebuild`, so this runs as a plugin
 * every time, like its siblings in this folder.
 */
module.exports = function withOptionalPortrait(config) {
  return withAndroidManifest(config, (config) => {
    const manifest = config.modResults.manifest;
    const features = manifest["uses-feature"] ?? [];
    const existing = features.find((feature) => feature.$["android:name"] === "android.hardware.screen.portrait");

    if (existing) {
      existing.$["android:required"] = "false";
    } else {
      features.push({ $: { "android:name": "android.hardware.screen.portrait", "android:required": "false" } });
    }
    manifest["uses-feature"] = features;
    return config;
  });
};
